<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Order;use App\Services\{OrderService,OrderStateMachine};use App\Jobs\GenerateInvoiceJob;use Illuminate\Http\Request;
class OrderController extends Controller {public function index(Request $r){$q=Order::with('customer')->when($r->status,fn($q,$s)=>$q->where('status',$s))->when($r->customer_id,fn($q,$id)=>$q->where('customer_id',$id))->when($r->from,fn($q,$d)=>$q->whereDate('order_date','>=',$d))->when($r->to,fn($q,$d)=>$q->whereDate('order_date','<=',$d))->latest();$p=$q->paginate(15);return response()->json(['success'=>true,'message'=>'OK','data'=>$p->items(),'meta'=>['page'=>$p->currentPage(),'per_page'=>$p->perPage(),'total'=>$p->total(),'total_pages'=>$p->lastPage()]]);}public function store(Request $r,OrderService $s){$v=$r->validate(['customer_id'=>'required|uuid|exists:customers,id','items'=>'required|array|min:1','items.*.product_id'=>'required|integer|distinct|exists:products,id','items.*.quantity'=>'required|integer|min:1']);$key=$r->header('Idempotency-Key');if(!$key||!\Illuminate\Support\Str::isUuid($key))return response()->json(['success'=>false,'message'=>'Idempotency-Key UUID wajib diisi'],422);return response()->json($s->create($v,$r->user()->id,$key),201);}public function show(Order $order){return response()->json(['success'=>true,'message'=>'OK','data'=>$order->load('items.product','customer','creator')]);}public function pay(Request $r,Order $order,OrderStateMachine $sm){\Illuminate\Support\Facades\DB::transaction(function()use($r,$order,$sm){$o=Order::lockForUpdate()->findOrFail($order->id);$sm->transition($o,'PAID',$r->user()->role);});GenerateInvoiceJob::dispatch($order->id)->afterCommit();return response()->json(['success'=>true,'message'=>'Paid','data'=>$order->fresh()]);}public function ship(Request $r,Order $order,OrderStateMachine $sm){abort_unless($r->user()->isAdmin(),403);$sm->transition($order,'SHIPPED','admin');return response()->json(['success'=>true,'message'=>'Shipped','data'=>$order]);}public function complete(Request $r,Order $order,OrderStateMachine $sm){abort_unless($r->user()->isAdmin(),403);$sm->transition($order,'COMPLETED','admin');return response()->json(['success'=>true,'message'=>'Completed','data'=>$order]);}public function cancel(Request $r,Order $order,OrderService $s){abort_unless($r->user()->isAdmin(),403);$v=$r->validate(['cancel_reason'=>'required|string|max:500']);return response()->json(['success'=>true,'message'=>'Cancelled','data'=>$s->cancel($order,$v['cancel_reason'],$r->user()->id)]);}public function invoice(Order $order){$path="invoices/{$order->id}.html";abort_unless(\Illuminate\Support\Facades\Storage::disk('local')->exists($path),404);return response(\Illuminate\Support\Facades\Storage::disk('local')->get($path))->header('Content-Type','text/html');}}
